@push('scripts')
    <script>
        (() => {
            const type = document.getElementById('accountType');
            const update = () => {
                const purchase = type.value === 'PURCHASE_PAYMENT';
                document.getElementById('accountCategoryWrap').classList.toggle('d-none', purchase || type.value === 'OTHER_INCOME');
                document.getElementById('accountPurchaseWrap').classList.toggle('d-none', !purchase);
                document.getElementById('accountDescriptionWrap').classList.toggle('d-none', purchase);
                document.getElementById('accountPurchase').required = purchase;
                document.querySelector('#accountDescriptionWrap input').required = !purchase;
            };
            type.addEventListener('change', update);
            update();
        })();
    </script>
@endpush
